var a=98;var n=[{id:`cooking-098-01`,theoryId:98,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why can overcooked cabbage develop a strong sulfurous smell?`,ua:`Чому переварена капуста може мати різкий сірковмісний запах?`},explanation:{en:`Brassicas contain sulfur compounds whose decomposition changes aroma.`,ua:`Капустяні містять сірковмісні сполуки, перетворення яких змінює аромат.`},options:[{id:`a`,text:{en:`Heating releases and transforms sulfur-containing compounds`,ua:`Нагрів вивільняє та змінює сірковмісні сполуки`}},{id:`b`,text:{en:`All sulfur comes from the pan metal`,ua:`Уся сірка походить із металу каструлі`}},{id:`c`,text:{en:`Chlorophyll becomes salt`,ua:`Хлорофіл перетворюється на сіль`}}],answer:{optionIds:[`a`]}},{id:`cooking-098-02`,theoryId:98,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Cutting and cooking can change the pungency of broccoli and mustard-family vegetables.`,ua:`Нарізання та приготування можуть змінювати гостроту броколі й інших капустяних овочів.`},explanation:{en:`Tissue disruption exposes enzymes and substrates; heat then changes reactions.`,ua:`Пошкодження тканин зближує ферменти й субстрати, а тепло змінює реакції.`},answer:{value:!0}},{id:`cooking-098-03`,theoryId:98,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match the preparation to a likely result.`,ua:`Поєднайте підготовку капустяних з очікуваним наслідком.`},explanation:{en:`Processing changes both texture and sulfur chemistry.`,ua:`Обробка змінює і текстуру, і сірковмісні речовини.`},leftItems:[{id:`l1`,text:{en:`Quick steaming`,ua:`Коротке приготування на парі`}},{id:`l2`,text:{en:`Prolonged overcooking`,ua:`Надмірно тривале варіння`}},{id:`l3`,text:{en:`Raw shredding`,ua:`Тонке шаткування сирої капусти`}}],rightItems:[{id:`r3`,text:{en:`Mechanical cell disruption`,ua:`Механічне руйнування клітин`}},{id:`r2`,text:{en:`More strong cooked-cabbage notes`,ua:`Сильніший запах вареної капусти`}},{id:`r1`,text:{en:`Tender-crisp broccoli`,ua:`Броколі м’яке, але з хрусткістю`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-098-04`,theoryId:98,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Brussels sprouts taste mushy and sulfurous. How can you improve the next batch?`,ua:`Брюссельська капуста розварена і має різкий сірковий запах. Як покращити результат?`},explanation:{en:`Avoiding excessive heat exposure preserves texture and more pleasant flavors.`,ua:`Менше теплове навантаження зберігає текстуру та приємніший смак.`},options:[{id:`a`,text:{en:`Cook for less time and test tenderness earlier`,ua:`Скоротити час та раніше перевірити готовність`}},{id:`b`,text:{en:`Boil for another hour`,ua:`Кип’ятити ще годину`}},{id:`c`,text:{en:`Cover and leave hot for several hours`,ua:`Накрити й тримати гарячою кілька годин`}}],answer:{optionIds:[`a`]}},{id:`cooking-098-05`,theoryId:98,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which statement about cruciferous vegetables is wrong?`,ua:`Яке твердження про капустяні овочі хибне?`},explanation:{en:`Normal cooking chemistry can create sulfur aromas; evaluate spoilage separately.`,ua:`Сірковмісний аромат може виникати під час звичайного приготування; псування оцінюють окремо.`},options:[{id:`a`,text:{en:`They contain sulfur compounds`,ua:`Вони містять сірковмісні сполуки`}},{id:`b`,text:{en:`Cooking can change odor`,ua:`Приготування може змінювати запах`}},{id:`c`,text:{en:`A strong sulfur smell always means microbial spoilage`,ua:`Сильний сірковий запах завжди означає мікробне псування`}}],answer:{optionIds:[`c`]}}];var i={theoryId:98,exercises:n};export{i as default,n as exercises,a as theoryId};